// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 5 ether);
        vm.deal(bob, 1 ether);

        vm.prank(alice);
        c.deposit{value: 5 ether}();

        vm.prank(alice);
        c.withdrawAll();

        vm.prank(bob);
        c.deposit{value: 1 ether}();

        uint balBefore = address(alice).balance;
        vm.prank(alice);
        c.withdrawAll();
        uint balAfter = address(alice).balance;
        assertTrue(balAfter == balBefore, "Alice should not receive any additional ether on second withdrawAll");
    }
}
